import json, os, re
from datetime import datetime, timezone
from html import escape

DATE='2026-11-06'; STAMP='20261106'; ROOT='/root/Projects/artifact-library/artifacts/daily-ingest'; os.makedirs(ROOT, exist_ok=True)

lanes=[
 {"slug":"open-agent-infrastructure","title":"Open Agent Infrastructure","rationale":"A fresh CNCF handoff makes agent sandboxes, suspend/resume, and post-training infrastructure a shared platform concern rather than a cloud-vendor feature.","readout":"The important move is not another agent SDK. It is a neutral runtime layer that can pause stateful agents, isolate untrusted code, and reuse compute across clouds and hardware.","items":[
  ("Powering open infrastructure for autonomous agents","https://cloud.google.com/blog/products/containers-kubernetes/open-infrastructure-for-autonomous-agents-comes-to-cncf","release","2026-11-05","Google is moving Agent Substrate, gVisor, and OpenRL into CNCF governance; Agent Substrate is 1.0 and GA on GKE.","Prototype a vendor-neutral Buildn worker contract with explicit state snapshots, policy gateways, and pluggable isolation.","Check the CNCF project status and run a small suspend/resume benchmark.","The performance and governance claims are vendor-reported; validate on your workload."),
  ("Agent Substrate on GKE","https://docs.cloud.google.com/kubernetes-engine/ai-ml/about-agent-substrate","docs","2026-11-05","The runtime separates stateful actors from warm workers and restores paused sessions in under 500 ms according to Google.","Use the actor/worker split as a reference architecture for long-running jobs that wait on human review or external tools.","Map one current Hermes job onto actor, gateway, snapshot, and worker responsibilities.","Managed GKE availability may not match a local or multi-cloud deployment model."),
  ("gVisor","https://gvisor.dev/","project","2026-11-05","A userspace application kernel offers a stronger boundary for agents that execute generated code or untrusted packages.","Offer isolated per-task execution for client analysis and code repair without granting a job a shared host-kernel trust level.","Compare gVisor with the current sandbox boundary using a hostile-package test.","Isolation is not permission management; network and secret policy remain separate."),
  ("OpenRL","https://openrl.dev/","project","2026-11-05","OpenRL targets self-hosted post-training infrastructure, widening the open stack beyond inference and orchestration.","Keep experiments and evaluation data in a controllable environment instead of coupling every improvement loop to a hosted API.","Read the API surface and identify one evaluation loop worth reproducing locally.","Post-training systems can add substantial compute, data, and reproducibility burden."),
  ("Agent Substrate repository","http://ate.dev/","repo","2026-11-05","The open project is the practical entry point for inspecting lifecycle APIs, storage assumptions, and runtime boundaries.","Use it as an architecture comparator before extending Buildn's own execution plane.","Open the repository, record its state model, and list three compatible seams.","Early CNCF projects may change APIs quickly during community onboarding.")]},
 {"slug":"cybersecurity-agents","title":"Cybersecurity Agents + Defensive Scope","rationale":"Two fresh disclosures show a capability jump in vulnerability research and a corresponding need for narrow scopes, evidence, and human-controlled release paths.","readout":"Security agents are becoming useful enough to find real flaws. The operational differentiator is now containment: authorized targets, reproducible evidence, patch ownership, and explicit stop conditions.","items":[
  ("GPT-6 Cyber","https://openai.com/index/introducing-gpt-6-cyber/","research","2026-11-05","OpenAI reports materially stronger exploit validation and scope adherence, with use in Linux, Firefox, code review, and infrastructure hardening.","Test a defensive review workflow that produces findings and candidate patches without granting an agent unrestricted attack surface.","Read the system card, then define an allowlisted lab target and evidence schema.","Vendor benchmarks and reported findings need independent validation; never use production targets by default."),
  ("A thousand fewer paths to root","https://openai.com/index/a-thousand-fewer-paths-to-root/","case study","2026-11-05","The companion report describes automated Linux vulnerability reproduction, disclosure, and patch contribution at unusual scale.","Borrow the handoff pattern: reproduce, minimize, disclose, patch, and retain an auditable artifact for every finding.","Draft a five-state vulnerability workflow for client code review.","Exploit generation is dual-use; isolate credentials, targets, and outbound communication."),
  ("Disrupting an AI-orchestrated cyber espionage campaign","https://www.anthropic.com/news/disrupting-AI-espionage","incident","2026-11","Anthropic describes an operation where an agent researched targets, wrote exploit code, and automated much of the intrusion chain.","Treat agentic security as an operating-plane problem involving identity, tool permissions, rate limits, and detection—not only model policy.","Add an agent-specific threat scenario to the next client security review.","The account is provider-reported and should be read alongside independent incident evidence."),
  ("Mapping AI-enabled cyber threats","https://www.anthropic.com/news/AI-enabled-cyber-threats-mitre-attack","framework","2026-10","Mapping observed AI-enabled behavior onto MITRE ATT&CK gives defenders a shared vocabulary for detection and control design.","Turn agent traces into ATT&CK-linked evidence so client teams can see which controls failed and where to instrument.","Create a lightweight trace-to-technique worksheet.","Framework mapping can create false confidence if telemetry is incomplete."),
  ("Securing our frontier model training environment","https://openai.com/index/securing-our-frontier-model-training-environment/","security","2026-10","The practical lesson is that model infrastructure itself needs continuous discovery, hardening, and attack simulation.","Apply the same loop to Buildn: inventory tool surfaces, run bounded probes, and track remediation as evidence-bearing work.","Inventory one agent's tools, secrets, network paths, and approval gates.","Do not infer that a model-assisted review replaces conventional security engineering.")]},
 {"slug":"private-multimodal-and-creative-tools","title":"Private Multimodal + Creative Tools","rationale":"Coverage has leaned heavily toward agent infrastructure; this lane deliberately follows a practical edge and creative gap: local multimodal retrieval and fast video iteration.","readout":"The useful frontier is becoming cheaper, more local, and more media-native. Small teams can turn private audio, video, and visual assets into searchable working memory without sending every byte to a hosted service.","items":[
  ("EmbeddingGemma 2","https://blog.google/innovation-and-ai/technology/developers-tools/embeddinggemma-2/","model","2026-10","Google describes a 740M-parameter multimodal embedding model designed for on-device search across code, images, video, and audio.","Build a private asset index for client references, meeting audio, and design evidence that remains useful offline.","Measure retrieval quality on a small mixed-media folder before adopting a hosted vector service.","Model size and reported storage gains do not guarantee acceptable latency on every device."),
  ("Gemini Omni 1.2 Flash","https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/","release","2026-11","The model adds native 15-second video generation and editing with claimed consistency improvements and lower pricing.","Use it for rapid storyboard variants, short explainers, and client concept tests before committing to production polish.","Create three controlled edits from the same brief and compare consistency, speed, and review effort.","Generated media still needs rights checks, brand review, and human selection."),
  ("Google AI updates: October 2026","https://blog.google/innovation-and-ai/technology/ai/google-ai-updates-october-2026/","roundup","2026-11-02","The roundup connects local multimodal search, interactive simulation, content provenance, and scientific review into one broader product direction.","Use it as a scouting map for private search, creative prototyping, and evidence-bearing research rather than as a shopping list.","Pick one capability and write a one-week experiment with an acceptance test.","The page includes AI-generated summaries and many marketing claims; follow primary product docs."),
  ("Deep Review for technical papers","https://blog.google/innovation-and-ai/technology/research/research-capabilities-intelligence-2026/","research tool","2026-10","Google reports public access to a technical-paper review workflow alongside other scientific reasoning tools.","Compare its output contract with Buildn dossiers: claims, citations, uncertainty, and next experiments.","Run one paper through it and score citation coverage manually.","Research assistance is not peer review; provenance and expert judgment remain required.") ]}
]

def logo(): return '<svg viewBox="0 0 164 195" width="22" aria-hidden="true"><path d="M117 194.5H0L12 73C17 67 21 65 29 64L35 0H152C158 4 161 7 164 13L153 120C149 127 145 130 136 131L131 185C128 190 125 193 117 195Z" fill="#01dc82"/><path d="M64 33L61 65H94L91 97H123L128 47C126 38 122 35 113 33H64Z" fill="#033330"/><path d="M37 148L42 98H75L72 130L104 131L101 162H50C42 159 40 156 37 148Z" fill="#033330"/></svg>'

def css(): return '''<style>:root{--brand:#01dc82;--deep:#033330;--lime:#cfe66a;--red:#b3261e;--amber:#9a6700;--ink:#0f172a;--muted:#475569;--line:#e2e8f0;--bg:#fafaf9;--card:#fff;--serif:Newsreader,Georgia,serif;--sans:"Plus Jakarta Sans",system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.55}main{max-width:66rem;margin:auto;padding:3rem 1.5rem}header{display:flex;flex-direction:column;gap:1rem;margin-bottom:2rem}.wordmark{display:flex;align-items:center;gap:.6rem;font-weight:700;color:var(--deep)}h1,h2{font-family:var(--serif);color:var(--deep);font-weight:600}h1{font-size:2.1rem;margin:0}h2{font-size:1.35rem;margin:0 0 .45rem}h3{font-size:.9rem;margin:1rem 0 .25rem;color:var(--deep)}a{color:#087f58}.dek{max-width:58rem;color:var(--muted);font-size:1.02rem}.meta{font:.78rem ui-monospace,monospace;color:var(--muted)}section{display:flex;flex-direction:column;gap:1rem}.card{background:var(--card);border:1px solid var(--line);border-radius:.75rem;padding:1.4rem;margin:1rem 0}.badges{display:flex;flex-wrap:wrap;gap:.45rem;margin:.25rem 0 .8rem}.badge{font-size:.68rem;text-transform:uppercase;letter-spacing:.06em;font-weight:700;padding:.15rem .5rem;border-radius:.35rem;background:#f1f5f9;color:var(--muted)}.good{background:#dcfce7;color:#166534}.warn{background:#fef3c7;color:var(--amber)}.spec{background:#e2e8f0;color:#334155}.facts{font:.78rem ui-monospace,monospace;color:var(--muted);list-style:none;padding:0;margin:.5rem 0 1rem}.facts li{padding:.1rem 0}.diagram{border:1px solid var(--line);border-radius:.5rem;background:#fff;padding:1rem;margin:1rem 0}.diagram svg{display:block;max-width:100%;height:auto}.label{font-size:12px;letter-spacing:.04em;fill:var(--muted)}.wins{margin:.5rem 0 0;padding-left:1.1rem}.wins li{margin:.18rem 0}.callout{border-left:3px solid var(--amber);background:#fffbeb;color:#713f12;padding:.6rem .9rem;border-radius:.25rem;font-size:.9rem}.matrix{width:100%;border-collapse:collapse;font-size:.86rem}.matrix th,.matrix td{border-bottom:1px solid var(--line);padding:.65rem;text-align:left;vertical-align:top}.matrix th{color:var(--deep);font-size:.72rem;text-transform:uppercase;letter-spacing:.05em}.top{border-top:4px solid var(--brand)}.source-trail{columns:2;column-gap:2rem}.source-trail li{break-inside:avoid;margin:.35rem 0;font-size:.86rem}</style>'''

def diagram(items):
 labels=[x[0][:22] for x in items[:5]]; w=max(520, len(labels)*125); parts=[f'<svg viewBox="0 0 {w} 150" role="img" aria-label="Signal map for the lane"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#94a3b8"/></marker></defs>']
 cx=w/2; parts.append(f'<circle cx="{cx}" cy="75" r="30" fill="#cfe66a" stroke="#033330"/><text x="{cx}" y="72" text-anchor="middle" class="label">BUILDN</text><text x="{cx}" y="88" text-anchor="middle" class="label">LEVERAGE</text>')
 for i,l in enumerate(labels):
  x=55+i*((w-110)/(max(1,len(labels)-1))); y=20 if i%2==0 else 105
  parts.append(f'<line x1="{cx}" y1="75" x2="{x}" y2="{y+12 if y<50 else y-12}" stroke="#94a3b8" marker-end="url(#arrow)"/><rect x="{x-48}" y="{y-12}" width="96" height="24" rx="5" fill="#fff" stroke="#cbd5e1"/><text x="{x}" y="{y+4}" text-anchor="middle" class="label">{escape(l)}</text>')
 parts.append('</svg>'); return ''.join(parts)

def page(lane):
 slug,title,rationale,readout,items=lane['slug'],lane['title'],lane['rationale'],lane['readout'],lane['items']
 cards=[]
 for i,(name,url,typ,date,what,use,action,caveat) in enumerate(items,1):
  cards.append(f'<article class="card" id="item-{i}"><h2>{escape(name)}</h2><div class="badges"><span class="badge good">selected</span><span class="badge spec">{escape(typ)}</span></div><ul class="facts"><li>updated: {date}</li><li>source: <a href="{url}">{escape(url.split("/")[2])}</a></li></ul><h3>What it is</h3><p>{escape(what)}</p><h3>Buildn / client use</h3><p>{escape(use)}</p><h3>Follow-up</h3><p>{escape(action)}</p><div class="callout"><strong>Caveat:</strong> {escape(caveat)}</div></article>')
 matrix='''<table class="matrix"><thead><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflow</th><th>Personal leverage</th></tr></thead><tbody><tr><td>Runtime</td><td>Stateful jobs, snapshots</td><td>Safe task sandboxes</td><td>Pause/resume loops</td><td>Cheap experiments</td></tr><tr><td>Evidence</td><td>Trace + artifact contracts</td><td>Reviewable deliverables</td><td>Scoped tool calls</td><td>Repeatable learning</td></tr><tr><td>Adoption</td><td>Open seams</td><td>Lower vendor lock-in</td><td>Replaceable workers</td><td>Local-first options</td></tr></tbody></table>'''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Ingest Dossier — {escape(title)} — {DATE}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{css()}</head><body><main><header><div class="wordmark">{logo()}<span>Buildn</span></div><div class="meta">ADAPTIVE DAILY INGEST · {DATE}</div><h1>Daily Ingest Dossier — {escape(title)}</h1><p class="dek"><strong>Executive readout.</strong> {escape(readout)}</p><p class="meta">Selection rationale: {escape(rationale)}</p></header><section><article class="card"><h2>Signal map</h2><div class="diagram">{diagram(items)}</div><ul class="wins"><li>Fresh signal, not another model roundup</li><li>Practical surfaces for controlled delegation</li><li>Every item has a testable next step</li></ul></article>{''.join(cards)}<article class="card"><h2>Use-case matrix</h2>{matrix}</article><article class="card top"><h2>Top actions</h2><ol class="wins"><li>Open the strongest primary source and capture its architecture or evaluation contract.</li><li>Run one bounded experiment with explicit success criteria and a human review gate.</li><li>Record the result as an artifact: inputs, environment, evidence, decision, next action.</li></ol></article><article class="card"><h2>Source trail</h2><ol class="source-trail">{''.join(f'<li><a href="{x[1]}">{escape(x[0])}</a></li>' for x in items)}</ol></article></section></main></body></html>'''

# write lane artifacts
for lane in lanes:
 path=f'{ROOT}/daily-ingest-{lane["slug"]}-{STAMP}.html'
 with open(path,'w',encoding='utf-8') as f:f.write(page(lane))

# overview
links=''.join(f'<li><a href="daily-ingest-{l["slug"]}-{STAMP}.html">{escape(l["title"])}</a><br><span class="meta">{escape(l["rationale"])}</span></li>' for l in lanes)
top=['Inspect Agent Substrate and gVisor as a neutral execution boundary.','Read GPT-6 Cyber with scope and evidence controls in mind.','Run a small private multimodal retrieval or creative-edit experiment.']
over=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Ingest Dossier — {DATE}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{css()}</head><body><main><header><div class="wordmark">{logo()}<span>Buildn</span></div><div class="meta">ADAPTIVE DAILY INGEST · {DATE}</div><h1>From agent infrastructure to defensible leverage</h1><p class="dek">Today’s dossier follows the practical control surfaces behind useful autonomy: open runtimes, defensive security agents, and private multimodal tools. The editorial thesis is simple: <span style="background:#cfe66a">capability compounds only when execution, evidence, and boundaries travel together.</span></p></header><section><article class="card"><h2>Selected lanes</h2><ol class="wins">{links}</ol></article><article class="card"><h2>All-lanes top three</h2><ol class="wins">{''.join(f'<li>{escape(x)}</li>' for x in top)}</ol></article><article class="card top"><h2>Editorial readout</h2><p>Freshest signal: Google’s CNCF move turns agent lifecycle management into open infrastructure. The most consequential counter-signal is cyber: frontier agents can now discover and validate vulnerabilities at operational scale, so scope and evidence are product requirements. A quieter but practical gap is local multimodal tooling, which can make private client material searchable and editable without defaulting to a hosted data plane.</p></article></section></main></body></html>'''
with open(f'{ROOT}/daily-ingest-overview-{STAMP}.html','w',encoding='utf-8') as f:f.write(over)

ledger={"date":DATE,"generated_at":datetime.now(timezone.utc).isoformat(),"editorial_thesis":"Useful autonomy is consolidating around three control surfaces: open runtimes that pause and isolate work, defensive security agents with strict scope, and private multimodal tools that keep practical leverage close to the data.","topic_groups":[]}
for l in lanes:
 sources=[]
 for n,u,t,d,w,use,a,c in l['items']:
  sources.append({"title":n,"url":u,"source_type":t,"published_or_updated":d,"why_selected":w,"usefulness":use})
 ledger['topic_groups'].append({"slug":l['slug'],"title":l['title'],"selection_rationale":l['rationale'],"sources":sources})
with open(f'{ROOT}/daily-ingest-{STAMP}.json','w',encoding='utf-8') as f:json.dump(ledger,f,indent=2,ensure_ascii=False)

# Update coverage memory and seen sources in archive repo
cov_path='/root/Projects/daily-ingest-pages/topic-coverage.json'
with open(cov_path,encoding='utf-8') as f: cov=json.load(f)
summary=cov.setdefault('rolling_theme_summary',{})
for l in lanes:
 e=summary.setdefault(l['slug'],{"title":l['title'],"times_covered":0,"last_covered":None}); e['times_covered']=e.get('times_covered',0)+1; e['last_covered']=DATE
history=cov.setdefault('recent_runs',[]); history.append({"date":DATE,"selected_lanes":[l['slug'] for l in lanes],"items":[{"title":x[0],"url":x[1],"source_type":x[2],"rationale":x[4]} for l in lanes for x in l['items']],"selection_rationale":"Fresh CNCF infrastructure and cyber disclosures plus a deliberate private-multimodal coverage gap."}); cov['recent_runs']=history[-45:]
with open(cov_path,'w',encoding='utf-8') as f:json.dump(cov,f,indent=2,ensure_ascii=False)
seen_path='/root/Projects/daily-ingest-pages/seen-sources.json'
with open(seen_path,encoding='utf-8') as f: seen=json.load(f)
seen['updated_at']=datetime.now(timezone.utc).isoformat(); src=seen.setdefault('sources',{})
for l in lanes:
 for n,u,t,d,w,use,a,c in l['items']:
  old=src.get(u,{"first_seen":DATE}); old['last_seen']=DATE; old['title']=n; src[u]=old
with open(seen_path,'w',encoding='utf-8') as f:json.dump(seen,f,indent=2,ensure_ascii=False)
print('generated',len(lanes)+1,'lane/overview html files plus ledger')
